import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%80%90%E6%9B%B8%E7%B1%8D%E3%80%91%E6%9C%80%E5%BC%B7%E3%81%AE%E9%9B%86%E4%B8%AD%E5%8A%9B.html","title":"【書籍】最強の集中力","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":7.85,"words":2356},"filePathRelative":"【書籍】最強の集中力.md"}`),a={name:`【書籍】最強の集中力.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="【書籍】最強の集中力" tabindex="-1"><a class="header-anchor" href="#【書籍】最強の集中力"><span>【書籍】最強の集中力</span></a></h1><p><a href="./書籍.html">書籍</a>, <a href="./雑多なメモ.html">雑多なメモ</a></p><p><a href="https://amzn.to/4v0rpoq" target="_blank" rel="noopener noreferrer">amazon: 最強の集中力 本当にやりたいことに没頭する技術</a></p><h2 id="購入-2026-03-27-金" tabindex="-1"><a class="header-anchor" href="#購入-2026-03-27-金"><span>購入 2026-03-27 (金)</span></a></h2><p><a href="./【書籍】ソーシャルメディアプリズム.html">【書籍】ソーシャルメディアプリズム</a>で名前が出てきて、気になったので購入。</p><p>最初に概要が載っていたのでメモしておく。</p><ul><li>最初のステップ: 注意散漫の発端が自分の内面にあることへの理解、コントロールする方法を学ぶ</li><li>パート2: 本当にやりたいことのための時間をつくる大切さに目を向ける。</li><li>パート3: 生産性を妨げ、幸福感を損なう外部誘引について掘り下げていく。</li><li>パート4: プリコミットメントについてとその有効性</li></ul><p>リファレンスがリンクになってないのがいまいち。<a href="./【書籍】ソーシャルメディアプリズム.html">【書籍】ソーシャルメディアプリズム</a>の方がずっといいな。</p><h2 id="スケジュールを決めろというのはいまいち好きになれない-2026-03-29-日" tabindex="-1"><a class="header-anchor" href="#スケジュールを決めろというのはいまいち好きになれない-2026-03-29-日"><span>スケジュールを決めろというのはいまいち好きになれない 2026-03-29 (日)</span></a></h2><p>自分はスケジュールを決めてないし、また、あまり決めたいとも思っていない。 そもそもサーフィンとかは波によるが、これは予想出来ないので自分で決めた通りに動けないものだ。</p><p>でも本書ではスケジュールを決めないと他人に奪われる、と書いているが、それには大した根拠も述べていない。 そもそもにそこはライフスタイルというか、どういう日常を送りたいかという価値観の話なので、 予定を決めなくてはいけない、というのは説得力も感じない。</p><p>自分は何やろっかな〜と思っている時間は大切なものだと思っているので、それを減らしてしまうのは良くないと思っている。 予定を建てるのはそういう考えからすると、いかにも駄目な時間の使い方だ。</p><p>その前までの感想も書いておく。</p><p>Part 1の最後の、ようするに自分に言い聞かせる言葉は前向きな言葉にしよう的な話も、因果関係と相関関係とかを誤魔化して話をしようとしていて、 どうも説得力を感じない。全体的にあまり学術的なものは感じない。 ここの他にもいろいろと主張はするが根拠は良く分からないものが多く、いまいち説得力を感じない本だなぁ。 ただ、前向きな言葉にしておく方がいいような気は直感的にもするので、別に異論はない。</p><p>序盤の方の、注意散漫の理由は、最初そんな事あるか？と思ったが、自分が注意散漫に陥る時の事を思い返すと割と思い当たる事があり、 説得された。また、対処法として10分後回しにするとかは、ポモドーロ法を使っている時に有効に機能している部分だと思っているので、 たぶんうまく機能するのだろうな、と思う。</p><p>ここまでの所は良いと思う所といまいちと思う所がある本だな。とりあえず参考になりそうな所だけ参考にしていこうと思う。</p><h3 id="使いたくない用途がある" tabindex="-1"><a class="header-anchor" href="#使いたくない用途がある"><span>使いたくない用途がある</span></a></h3><p>スケジュールを決めるのに反発があるなら、自分はどういうのが良いと思っているのか？というのを考えてみた。</p><p>自分は「こういう目的で時間を使いたい」という目的を達成したいのでは無く、「こういう用途には時間を使いたくない」という、 望ましくない時間の使い方が幾つかある、という事だと思う。 ようするに更新の無いtwitterを何度も確認したりどうせ読む価値が無いと思っているカクヨムのデイリーランキングのつまらなさそうな奴を読んだりするのを無くしたいのであって、 それ以外の使い方ならどれでも良いと思っている。</p><p>この良くないと思う用途は決まったリストがあるというよりは、日々の生活を振り返って「これはいまいちだな〜」と感じるものを減らしたい。</p><p>一方、勉強だとか仕事だとかでやらなきゃと思っている事が出来ていない訳では無い。むしろそこには不満は感じていない。</p><p>時間を有効に使いたいというよりは、不健康なものを減らしたい、という感じなんだよな。</p><p>そしてやる事の無い時間が出来たら何をやるかを考えていくのは結構有意義に思っている。これは先にやる事を決めるんじゃなくて、 「仕事とサーフィンと読書はまぁいい感じにできているが、もう一つくらい何かやる事欲しいな〜」みたいな感じで考えていくのが良い感じと思っている。 そしてそれが決まった後の日々よりも、それを考えている過渡期的な状態の方を人生において重要な時間だと思っている。</p><p>考えてみて、やりたくない用途の時間の使い方があってそれを減らしたいというのが自分の望みだ、というのは、腑に落ちた。 この本の最初の方の注意散漫に陥る理由は、自分の目的にも割と参考になる事もあるので、それらはうまく活用していきたい。</p><h2 id="スケジュールの話はやはりいまいち-2026-04-01-水" tabindex="-1"><a class="header-anchor" href="#スケジュールの話はやはりいまいち-2026-04-01-水"><span>スケジュールの話はやはりいまいち 2026-04-01 (水)</span></a></h2><p>11章は人との交流をスケジュールに組み込む、12章は仕事もスケジュールを組んで上司などと共有するという話だが、 どちらも自分はそうしてます、以上の何かを感じない。</p><p>仕事に関しては明らかにそんな事よりももっと優先する事があるし、それを放置して自分の時間管理で解決しようというのはいかにも考えが浅いという印象。</p><p>人との付き合い方も別にそれが良いという気はあまりしない。そういう人が居てもいいとは思うが、みんながそうしないといけないという何かがある感じでは無く、本編の集中力と関係ない自分語りという感じでいまいちだ。参考にもあまりならない。</p><p>著者の人間としての浅さが透けて見えてしまうなぁ。</p><h3 id="学術的である大切さ" tabindex="-1"><a class="header-anchor" href="#学術的である大切さ"><span>学術的である大切さ</span></a></h3><p><a href="./【書籍】ソーシャルメディアプリズム.html">【書籍】ソーシャルメディアプリズム</a>と比較すると、この本は学術的では無い。 単に自分のやり方が良い、と主張するだけで、そこに何かの理由づけとしてリファレンスを足すだけだ。 こうした本は説得力が低く、学ぶ事も少ないと思う。XXでなければいけない、といいながら、そうでないといけない根拠が無い（実際そんな訳無いだろう、という主張も多い）。</p><p><a href="./【書籍】ソーシャルメディアプリズム.html">【書籍】ソーシャルメディアプリズム</a>は、何かのトピックについて研究の結果を教えてくれる。 そこに自身の主張などはあるにせよ、研究自身にそれなりの重きを置いて伝えてくれる。 単に自分の主張を書いて、それの理由づけになる研究を並べるというやり方では無い。 その結果として意見には同意出来なくても「そんな研究があるのか」という事は参考になるし、 結論に納得が出来なくても「少なくともこういう研究はあるのか」と、部分的に学ぶ事が出来る。</p><p>この本は著者の思い込み的な何かに同意出来ないと、そこの節は何も学ぶ事が無くなってしまう。 学ぶ事がある節もあるので駄目な本とまでは思わないけれど、 同じ時間を使って本を読んだ意義は薄くなってしまう。</p><p>この本は得るものはあるという点で読んでいる意義は感じるが、 こういう本が減って<a href="./【書籍】ソーシャルメディアプリズム.html">【書籍】ソーシャルメディアプリズム</a>みたいな本が増えて欲しいなぁ、とは思う。</p><h2 id="part3の外部誘引にハックするは、読む意義を感じる-2026-04-04-土" tabindex="-1"><a class="header-anchor" href="#part3の外部誘引にハックするは、読む意義を感じる-2026-04-04-土"><span>part3の外部誘引にハックするは、読む意義を感じる 2026-04-04 (土)</span></a></h2><p>内容はメールを決まった時間にだけ見るようにしよう、とかそういう話で、自分が自己流で考えて適当にやっている事に比べて何か優れているという感じは無い。 だが、手段の良し悪しを超えて、注意散漫についていろいろと語られている文章を読む、という事自体に効果がある事を実感する。</p><p>また、内容自体も凡庸ではあるが、反発を覚えるようなものは無い。もっと根本的な事に対策した方がいいだろう、と思うような事もあるけれど、 状況が悪い時になんとか自分の集中を死守する話と思えば他人の話として普通に読める。 実際自分も新卒の頃の会社ではこういう状況でなんとかコーディングの時間を死守しようとしていたので、そういう状況もあるよな、とは思える。</p><h3 id="注意散漫という事について考える意義" tabindex="-1"><a class="header-anchor" href="#注意散漫という事について考える意義"><span>注意散漫という事について考える意義</span></a></h3><p>メールとかチャットなど、それぞれについての注意散漫の話を見ると、 自分の注意散漫による行動が注意散漫であると自覚しやすくなる。 これがpart3を読む一番の意義に思えた。 実際の対策よりも、その対策を取ろうとしている事を問題として提示するのを繰り返す事で、 似たような事も注意散漫というカテゴリとして自覚出来るようになる。</p><p>いろいろな例での注意散漫の記述を見ていく事で、そこに挙げられていないものでも「これは注意散漫だな」と思うようになる。 例えば本を読んでいて関係無い事のブログを書きたくなる、みたいなのも注意散漫だと気づける。</p><p>しかもなぜそういう注意散漫の行動を取ろうとしたのか、という事については、本書の序盤の内部誘引の話を思い出して、 自分の中の何が今そういう行動を取らせようとしたのか、と考えて、割と簡単に原因に思い至る。 原因に思い至ると、割と簡単に横道にそれずに戻ってこれる。</p><p>たぶん内部誘引がどうこうというのはそこまで重要では無く、一瞬間を開けて冷静になる事に意味があるような気がする。 一瞬間をあける為にはそれが注意散漫だ、と気づくのが良くて、そして内部誘引について一瞬考える事で衝動から理性にスイッチが切り替えられて、 これが注意散漫を防いでくれる。</p><p>本を読んでいて、つい何かスマホを手に取りそうになった時に「これはいかにも注意散漫だな」と自覚してスマホを手に取るのを防げる事が増えた。</p><p>注意散漫という事に意識を向けるようになる、というのがpart3を読む一番の意義に思う。 そして本書を読む一番の恩恵でもあるように思う。</p><h3 id="twitterやfacebookの時間を決める" tabindex="-1"><a class="header-anchor" href="#twitterやfacebookの時間を決める"><span>twitterやFacebookの時間を決める</span></a></h3><p>ここ半年くらい、twitterとFacebookのタブを閉じておいて、一日一回くらいだけチェックするようにしていた。 どちらもそれほど有害とは思わない程度の付き合いは出来ているのだが、 無意味に何度も見てしまうという気がしていたので、それを改善するために考えた事だった。 まぁまぁ有効に機能していて、世間の話題と適切に距離はおきつつ完全には隔絶されないくらいに出来ている。</p><p>これは本書のpart3で提案されているやり方と同じものだなぁ、と読んでいて思った。</p><h3 id="野放し以上、ポモドーロ未満" tabindex="-1"><a class="header-anchor" href="#野放し以上、ポモドーロ未満"><span>野放し以上、ポモドーロ未満</span></a></h3><p>本を読んでいて、意外と違う事をやってしまおうとする事は多い。</p><p>これはポモドーロをやっていると思っていた事でもあり、 本当に進めたい事を進める時は素直にポモドーロする方が良いとも思うが、 この本を読む、というような、別段そこまで集中してやりたい訳でも無いが多少有意義と思える程度の時間を過ごしたい、 という時にはポモドーロは真面目すぎるな、とも感じている。</p><p>自分はどうしても集中したい時にはポモドーロで不満を持っていない。 一方でどうしても集中したい、というのはそれなりに大変なので、 重要な事以外ではあまり使わない。</p><p>本書を読むのは、ポモドーロを使わない程度に自由でそこまで重要では無いような事だが、 何もしていないといまいち進まずに一日が終わってしまってもうちょっとやりたいなぁ、と思う程度にはやりたい事をやるのに、 ちょうど良いくらいの注目を向けられている気がする。</p><p>スケジュールを組むとかポモドーロをやる、というのは、そこまでやりたい訳でも無い事には強すぎる。 確実に今日、Aを1時間やりたい、と思っているならこれでいいのだが、 自分はあまりそういうのは無い。AかBかC、どれでも気が向いたのでいいのだが、どれかを1時間か2時間くらいやりたい、 みたいな、そういう曖昧性を持たせておきたい事が多い。</p><p>こういうやりたい気分の時にやりたい事をやる、という幸せをキープしつつ、 やりすぎて不毛だと思っている事に時間を使ってしまわないようにしたい、 程度の、ゆるい規律を求めている自分としては、本書の内容はちょうど良い情報を与えてくれている気がする。</p><p>注意散漫の類型をいろいろと見て、自分の注意散漫を自覚出来るようになって、一瞬そこで内部誘引に目を向ける。 このくらいが、自分のやりたい事とちょうどマッチしている気はした。</p><h3 id="暇つぶしと注意散漫" tabindex="-1"><a class="header-anchor" href="#暇つぶしと注意散漫"><span>暇つぶしと注意散漫</span></a></h3><p>例えば自分はSwitchでファイナルファイトをやっている。一日1時間くらいはやっているだろうか？今はロレント面のエレベータ前のあたりをやったりしている。 この時間は完全に暇つぶしであって、やるべき事では無い。 だが無くしたいと思っている事でも無い。 そのうちワンコインクリア出来るようになったら秋葉原にでも行ってゲーセンでワンコインクリアにチャレンジしたいと思っている。 そういう点で、やる事にある程度の意義は感じているのかもしれない。</p><p>ファイナルファイトで同じ所を繰り返すのはすぐに飽きるのでずっとやってしまう、という事も無い。だいたいこのくらいはやってもいいか、と思う程度しかやらない。 だからやりすぎないように気をつける必要も感じない。</p><p>最近はあまりやってないが、将棋とか囲碁も同じように感じている。 やるべき事では無いのだが、やっても別に良いと思っている。 将棋動画を見る時間も減らしたいとは思っていない。</p><p>そして一日の中で、この「やるべきという訳でも無いがやっても良い事」の時間はある程度あるようにしたいと思っている。 これは一日の余裕というかあそびというか、他の事との緩衝地帯みたいになっていて、一日のストレスを下げるのに役に立っている気がしている。</p><p>一方で、twitterやFacebookで更新の無いタイムラインを何度も確認するのは無駄だと思っている。 また、どうでもいいが反発を覚えるようなRTに反発を覚えるのは有害だとも思っている。 カクヨムも全く更新が無いのでデイリーランキングから、いかにもつまらなさそうだがまだ読んでないのを選んで読むのも無駄だと思っている。 こういう無駄な時間は減らしたいと思っている。</p><p>カクヨムはまぁまぁ面白いと思っているものの更新を読んでいくのは有意義に思っている。 つまらないと思っているものを読んでしまうのは良くないと思っている。 この辺はやっていて「これは不毛だな」と思うかどうかで線引されているように思う。</p><p>暇つぶしとか有意義でない事を無くしたい、とは思っていないんだよな。 なんというか、制御下において適切な量だけやりたい、と思っているんだと思う。 そして、現状はそれなりには上手く行っていて、何か破綻していたり根本的な立て直しが必要とも思っていない。 たまに不毛な方にはみ出してしまう事があって、それを個別に対処している。 そのくらいでいいのではないか、という気はしている。</p><h3 id="やらなくてはいけない事を低くおさえる" tabindex="-1"><a class="header-anchor" href="#やらなくてはいけない事を低くおさえる"><span>やらなくてはいけない事を低くおさえる</span></a></h3><p>自分がこの問題で一番上手くやれている、と思うのは、やらなくてはいけない事を少なく抑えられている事に思う。 具体的には仕事をフルタイムにしていない事だ。 やる気が出ない時にやらない、という事を選んで特に問題がない量におさえている。 そしてこれは、凄く重要な事のようにも思う。</p><p>仕事をフルタイムでやらなくてはいけないなら、もっと集中してやるためにいろいろな事を考えなくてはいけないだろう。 だが、それは結構高い緊張を維持する事になる。 出来なくはないとは思うが、やりたい事では無い気がする。</p><p>今の仕事量は、やる気が無い時はやらなくても問題が無い程度になっている。 やる気が出ない、というのを肯定出来て、あまりにも続いた時にちょっと対処が必要な程度だ。 これは不摂生になりすぎない程度にちょうど良い規律にもなっていて、もっと減らしたいとは思っていないくらいの緊張になっている。</p><p>たぶんこのやらなくてはいけない事を今の自分くらいに抑える、というのは、 このトピックにおいては凄く重要な話に思う。 ただ簡単では無いので、本などにしてもウケないんだろうな。</p><h2 id="読了-いまいちな内容も多いが、全体としては役に立った-2026-04-13-月" tabindex="-1"><a class="header-anchor" href="#読了-いまいちな内容も多いが、全体としては役に立った-2026-04-13-月"><span>読了：いまいちな内容も多いが、全体としては役に立った 2026-04-13 (月)</span></a></h2><p>読み終わった。本書は半分以上ぱっとしない内容だが、それでもかなり役に立ったので読む価値がある気はしている。</p><h3 id="後半の内容は全体的にいまいち" tabindex="-1"><a class="header-anchor" href="#後半の内容は全体的にいまいち"><span>後半の内容は全体的にいまいち</span></a></h3><p>Part4のプリコミットメント、Part5の職場の環境、Part6の子育て、Part7の友人関係は、総じていまいちだった。</p><p>Part4のプリコミットメントは本当にどうしてもやらなくてはいけない時に有効に使えるだろうとは思うが、 そこまでしてやりたい事が出来ていない訳では無いしなぁ、という印象。 実際本書でも、使いすぎるとうまく機能しないと書いてあるので、本当にどうにもならない時くらいしか使わないよな。 そしてどうしてもこういうのが必要になった時に、本書を読んでなくても別ににたような事はどうせやる。</p><p>Part5の職場環境は、企業の風土というより大きな問題を扱う事なく注意散漫の側面だけに言及するので、別段説得力も感じない。 本当の問題にアプローチせずにこういう所だけ頑張っても仕方ないだろうし、それはまさに本書の前半の主張ではないか、という気もする。</p><p>Part6の子育ては、そもそも子育てしないしなぁ、という印象。それはそう。 しかもXXはこう言っている、をダラダラ書いてばかりで、その人がなぜ説得力があると思うのかとかが書いてないので、 一体何を伝えたいのかさっぱり分からない。 ただ子供とスマホとかを触りすぎる問題を話し合うのは家庭としてはやった方が良さそうだな〜という気はした。 でも子育てしてないので本当にそうかは良くわからんよな。</p><p>この辺の話は、むしろ子育てしている人に持論を聞いてみたいな、という気がする。</p><p>Part7の友人関係は、まぁカフェなどで会って話をしている時にスマホとかいじってるのは感じ悪いよな、とは思うが、それは本書を読まなくてもそれはそうだろう、という気もする。 あまりにも酷い時には話し合いも必要だが、皆すでにそれなりに気をつけている気もするので、別にこの章を読む必要性はあまり感じないかな。</p><p>という事で全体的に後半はいまいち。というか序盤以外いまいちな本だ。</p><h3 id="内部誘引と外部誘引の章は実際に効果がある" tabindex="-1"><a class="header-anchor" href="#内部誘引と外部誘引の章は実際に効果がある"><span>内部誘引と外部誘引の章は実際に効果がある</span></a></h3><p>という訳でいまいちな本に見えるが、自分の評価はかなり高い。</p><p>というのは、この本を読んでいる時に実際に本を読むのに集中するのが容易になった。具体的にご利益があるというのは凄い。</p><p>本書の内容で役に立ったのはPart 1の内部誘引とPart 3の外部誘引の話。それ以外は著者のやっている事が書かれているだけで、それが良いという気も別段しないので真似したくもないし、役に立たない。</p><p>という事でPart 1の内部誘引とPart 3の外部誘引の章だけがこの本の価値という気がする。</p><h3 id="part-1-の内部誘引は、実際にそうだと体感する事が多く、有効である" tabindex="-1"><a class="header-anchor" href="#part-1-の内部誘引は、実際にそうだと体感する事が多く、有効である"><span>Part 1 の内部誘引は、実際にそうだと体感する事が多く、有効である</span></a></h3><p>Part 1の内部誘引の話は、SNSとかをすぐ触ってしまうのは、苦痛からの逃避だ、みたいな話で、苦痛の方をどうにかしないといけない、 という話。 ほんまかいな、と思ったし、実際本書の記述は実際に自分が注意散漫になる時の理由とはかけ離れている。 だが、Part 1を読んだ後に続きを読んでいって、ふとwebとかを見たくなった時に、 「なんで今自分はwebを見たくなったのだろう？」と考えてみると、 確かに小さな不快感のようなものがある事が多い、という事を知った。 そしてその正体に思いをはせると、すぐに心が本に戻ってきて続きを読み進められる。</p><p>Part 1の内容の素晴らしい事は、読んだ後に実際に自分が注意散漫になる時に、 何故いま注意散漫になったのか？という所に注意を向けるようになるからだ。 そしてその不快感の正体を直視すると、だいたい大した事は無いのですぐに乗り越えられる。 ついスマホを見てしまう衝動を簡単に抑える事が出来る。素晴らしい。</p><p>この内部誘引が何なのかを少し考えて直視する、というのは、簡単なのに分かりやすく効果がある。</p><p>ちなみに自分が本を読むのに集中出来ないケースでは、だいたいは本の内容の不快さに起因していた。 因果関係を示せていない事を因果関係のように書いていたり、他人の研究を列挙するがなぜその人の研究が正しいと思ったのかが書かれていなかったり、 といった、内容の不愉快さを感じるとwebを見たくなるようだ。</p><h3 id="part-3の外部誘引は、そういうカテゴライズでものを見るようになる所が良い" tabindex="-1"><a class="header-anchor" href="#part-3の外部誘引は、そういうカテゴライズでものを見るようになる所が良い"><span>Part 3の外部誘引は、そういうカテゴライズでものを見るようになる所が良い</span></a></h3><p>そしてPart 3の外部誘引の話はSNSとかメールとかチャットとかに気が散りがちなのでどうにかしましょう、という話で、どうするかの対処法は凡庸なものばかりで別段良いと思うものでも無い。 そしてSNSとかメールとかチャットとかに気が散りがちというのも別段驚きの内容でも無いだろう。 そういう訳で、Part 3の内容は別段情報として価値があるようにも見えない。</p><p>だが、こういう風に注意散漫という視点でまとめたものを読むと、 実際に何かの通知が来て気が散った時に、お、これは注意散漫の外部誘引だな、と思うようになる。 そして、通知をオフにしたり不要になったメールのunsubscribeをしたりミュートしたり、という事をするようになる。 この、いろいろなものを注意散漫の外部誘引というレッテルを貼って偏見で見る事が有効に機能する。 本書の続きを読んだ時に実際に機能したので、このPart 3の内容も素晴らしい、と認めたい。</p><p>通知が来てもすぐに反応するのは本書の言われた通りになっているようで「しゃく」なので、ちょっと置いてから反応するようになる。 ちょっと置けば基本的には注意散漫には陥らずに集中を続けられるので、これもかなりの効果がある。</p><h3 id="ダイエット本を読んで食生活を気をつけるような効果のある本" tabindex="-1"><a class="header-anchor" href="#ダイエット本を読んで食生活を気をつけるような効果のある本"><span>ダイエット本を読んで食生活を気をつけるような効果のある本</span></a></h3><p>この本は新しい情報を得るというよりは、食生活に関する本を読んで「ちょっと最近食が乱れているので気をつけるか」と思い直すような効果がある。</p><p>著者はおそらくすぐに注意散漫になってしまうタイプの人間で、読んでいると「いや、そこまでは無いが？」という気がしてしまう事も多い。 そして対策も極端なのが多くて全然良さそうでは無いし、参考にもならない。 だが、そういう著者を見るのは、アル中の人の生活を見てアルコールを控えようと思うような、 人の振り見て我が振り直せ的な効果がある。 それがこの本の意義のようにも思う。</p><p>読んだ結果がずっと続くかは分からないが、たまにこういう本を読んで背筋を正すのは悪くないな、と思った。</p><p>ただ、そういう目的で読むには、内容の同意できない部分の多さがちょっといまいちな本でもある。</p><p>それでも実際に本を読む時に明確に効果があったので、高い評価を与えてあげよう。</p>`,98)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};